import { useCallback, useEffect, useState } from 'react'

const STORAGE_KEY = 'folio:favorites:v1'
const STORAGE_ERROR_KEY = 'folio:favorites-error:v1'

export type FavoritesError = 'storage_error' | null

export function getStoredIds(): string[] {
  try {
    const stored = localStorage.getItem(STORAGE_KEY)
    if (!stored) return []

    const parsed = JSON.parse(stored)
    if (typeof parsed !== 'object' || parsed === null || !('version' in parsed) || !('ids' in parsed)) {
      return []
    }

    if (parsed.version !== 1) {
      return []
    }

    if (!Array.isArray(parsed.ids)) {
      return []
    }

    const ids = parsed.ids
    if (ids.some((id: unknown) => typeof id !== 'string')) {
      return []
    }

    const uniqueIds = Array.from(new Set(ids))
    return uniqueIds.sort()
  } catch {
    return []
  }
}

export function saveIds(ids: string[]): boolean {
  try {
    const normalized = [...new Set(ids)].sort()
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ version: 1, ids: normalized }))
    return true
  } catch {
    return false
  }
}

export function clearIds(): boolean {
  try {
    localStorage.removeItem(STORAGE_KEY)
    return true
  } catch {
    return false
  }
}

export function clearStorageError(): boolean {
  try {
    localStorage.removeItem(STORAGE_ERROR_KEY)
    return true
  } catch {
    return false
  }
}

export function hasLocalStorageError(): boolean {
  try {
    localStorage.removeItem(STORAGE_ERROR_KEY)
    return false
  } catch {
    return true
  }
}

function setStorageError(): void {
  try {
    localStorage.setItem(STORAGE_ERROR_KEY, 'true')
  } catch {
    // Ignore if storage is completely unavailable
  }
}

export function useFavoritesStorage() {
  const [favorites, setFavorites] = useState<string[]>([])
  const [error, setError] = useState<FavoritesError>(null)

  const loadFavorites = useCallback(() => {
    const newFavorites = getStoredIds()
    setFavorites(newFavorites)
    // Clear error if storage works
    try {
      localStorage.removeItem(STORAGE_ERROR_KEY)
    } catch {
      // Storage still unavailable
    }
  }, [])

  useEffect(() => {
    const storedError = hasLocalStorageError()
    if (!storedError) {
      loadFavorites()
      setError(null)
      return
    }

    // Reset error on page refresh
    clearStorageError()
    loadFavorites()
    setError(null)
  }, [])

  useEffect(() => {
    if (error) {
      loadFavorites()
    }
  }, [error])

  useEffect(() => {
    if (error) {
      window.addEventListener('storage', handleStorageEvent)
      return () => window.removeEventListener('storage', handleStorageEvent)
    }
  }, [error])

  const addFavorite = useCallback((id: string) => {
    setFavorites(current => {
      if (current.includes(id)) return current
      const newIds = [...new Set([...current, id])].sort()
      // Don't persist yet (wait for storage event)
      return newIds
    })

    // Trigger write to storage
    try {
      saveIds(getStoredIds().concat([id]))
    } catch {
      setStorageError()
      setError('storage_error')
    }
  }, [])

  const removeFavorite = useCallback((id: string) => {
    setFavorites(current => {
      const newIds = current.filter(item => item !== id)
      // Trigger write to storage
      try {
        saveIds(newIds)
      } catch {
        setStorageError()
        setError('storage_error')
      }
      return newIds
    })
  }, [])

  const toggleFavorite = useCallback((id: string) => {
    if (favorites.includes(id)) {
      removeFavorite(id)
    } else {
      addFavorite(id)
    }
  }, [favorites, addFavorite, removeFavorite])

  const removeProjectFavorites = useCallback((projectIds: string[]) => {
    setFavorites(current => {
      const newIds = current.filter(item => !projectIds.includes(item))
      // Trigger write to storage
      try {
        saveIds(newIds)
      } catch {
        setStorageError()
        setError('storage_error')
      }
      return newIds
    })
  }, [])

  return {
    favorites,
    error,
    setFavorites,
    addFavorite,
    removeFavorite,
    toggleFavorite,
    removeProjectFavorites,
    clearStorageError,
    clearStorageErrorLocal: clearStorageError,
    checkStorageError: () => hasLocalStorageError(),
  }
}

